/**
 * Generate the committed tank table from the official Wargaming encyclopedia
 * API (phase 13, plan 13-02, D-07, D-08, D-09, T-13-06, T-13-07, T-13-08).
 *
 * ## Why this script exists and runs only on the maintainer's machine
 *
 * The table is API DATA, and D-07 commits it to a PUBLIC repository. It is
 * therefore generated by a script that only the maintainer runs, with a key
 * that only the maintainer holds, and it is committed by hand after the
 * Wargaming Terms-of-Use checkpoint (plan 13-15) has passed. CI NEVER calls
 * the API: the only script CI could run is `--check`, which is offline.
 *
 * ## Why the key never appears anywhere else
 *
 * The key is read from the process environment, or from ONE line of the
 * gitignored `.env.local` at the repository root. This file is the only code
 * in the repository that opens that file. The key is passed to the request
 * and to nothing else: it is not logged, not written into the generated
 * module, and not part of any error message (T-13-06). An error page from the
 * API can echo the offending parameter back in `error.value`, so only
 * `error.code` and `error.message` are ever printed — and the key is redacted
 * out of the message as well, because the message is payload too.
 *
 * ## Why the payload is validated before anything is written (T-13-07)
 *
 * The API response is untrusted input that becomes committed source, so the
 * validation in `lib/vehicle-table-build.ts` fails closed: a non-`ok` status,
 * a bad id, tag, nation, name, type or tier, a duplicate key, an empty
 * result or an oversized result aborts the run with a non-zero exit and the
 * output file is NOT touched.
 *
 * ## Why it runs as a plain Node `.ts` file
 *
 * `node scripts/vehicles/build-vehicle-table.ts` uses native type stripping,
 * so the build step for the build step does not exist. That only works while
 * the file stays erasable — no `enum`, no `namespace`, no parameter
 * properties — which `erasableSyntaxOnly` in `tsconfig.node.json` enforces.
 *
 * ## The flags
 *
 *   --out <path>      where to write (default: the one repository path)
 *   --from <json>     validate a SAVED payload instead of calling the API.
 *                     This exists for the tests and for re-running the
 *                     validation over a payload that was already fetched; it
 *                     never reaches the network.
 *   --empty           write the empty table (no rows, count 0).
 *   --check           prove the committed module is current, offline.
 *   --against <path>  change only WHICH file `--check` compares.
 *
 * An unknown flag is an error rather than a silent no-op.
 */

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import {
  MAX_ROWS,
  readApplicationId,
  renderModule,
  rowsHash,
  validatePages,
  validateRows,
} from './lib/vehicle-table-build.ts';
import type { VehicleTableRow } from './lib/vehicle-table-build.ts';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

/** The one path the generated table may be written to. */
const DEFAULT_OUT = 'src/lib/features/overview/vehicle-table.generated.ts';

/** The local env file, at the repository root, gitignored. */
const DEFAULT_ENV_FILE = '.env.local';

/** The API host and path. The key is a query parameter, never part of this. */
const API_ORIGIN = 'https://api.worldoftanks.eu';
const API_PATH = '/wot/encyclopedia/vehicles/';

/** The fields the table needs, and nothing else. */
const API_FIELDS = 'tank_id,tag,name,short_name,type,tier,nation,is_premium,is_gift';

/** The API's page size. */
const PAGE_LIMIT = 100;

/**
 * The most pages the generator will ever ask for (WR-06).
 *
 * The table holds at most {@link MAX_ROWS} rows and one page holds
 * {@link PAGE_LIMIT} of them, so a page count past that carries no row the
 * table could keep. One page of slack covers a final short page. The API's own
 * `page_total` is untrusted: without this bound a malformed answer would make
 * the loop send that many key-bearing requests before any validation ran.
 */
const MAX_PAGES = Math.ceil(MAX_ROWS / PAGE_LIMIT) + 1;

/** The API allows 10 requests per second; a pause between pages keeps well under it. */
const PAGE_PAUSE_MS = 150;

/** One request may not take longer than this. */
const REQUEST_TIMEOUT_MS = 30_000;

interface Options {
  out: string;
  outExplicit: boolean;
  from: string | null;
  empty: boolean;
  check: boolean;
  against: string | null;
  envFile: string;
}

/** Parse the flags. An unknown flag is an error rather than a silent no-op. */
export function parseArgs(argv: readonly string[]): Options {
  const options: Options = {
    out: DEFAULT_OUT,
    outExplicit: false,
    from: null,
    empty: false,
    check: false,
    against: null,
    envFile: DEFAULT_ENV_FILE,
  };
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    const value = (): string => {
      const next = argv[i + 1];
      if (next === undefined || next.startsWith('--')) {
        throw new Error(`${arg} needs a value`);
      }
      i += 1;
      return next;
    };
    if (arg === '--check') options.check = true;
    else if (arg === '--empty') options.empty = true;
    else if (arg === '--out') {
      options.out = value();
      options.outExplicit = true;
    } else if (arg === '--from') options.from = value();
    else if (arg === '--against') options.against = value();
    // `--key-file` is NOT a user-facing flag: it exists so a test can point
    // the env-file lookup at a path that does not exist, and prove the script
    // fails closed without reading the repository's own `.env.local`. It is
    // NOT called `--env-file`, because Node itself owns that option and
    // intercepts it before the script ever sees it.
    else if (arg === '--key-file') options.envFile = value();
    else throw new Error(`unknown flag: ${arg}`);
  }
  return options;
}

/** Today's date in UTC, as `YYYY-MM-DD`. A date, never a time and never a host. */
export function todayUtc(now: Date = new Date()): string {
  return now.toISOString().slice(0, 10);
}

/** Whether a value is a plain object (and not an array, and not null). */
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** The env file's text, or null when it is absent or unreadable. */
async function readEnvFile(file: string): Promise<string | null> {
  try {
    return await readFile(file, 'utf8');
  } catch {
    return null;
  }
}

/**
 * The output path.
 *
 * The DEFAULT is resolved from the repository root, so the script writes the
 * one committed path no matter where it was invoked from. An explicit `--out`
 * is resolved from the current directory, which is what a test's temporary
 * path needs.
 */
function outputPath(options: Options): string {
  return options.outExplicit ? path.resolve(options.out) : path.resolve(REPO_ROOT, options.out);
}

/**
 * Fetch every page of the encyclopedia vehicle list.
 *
 * The key is the ONLY thing that goes into the request URL, and the URL is
 * never printed. The pages are fetched in order with a pause between them,
 * and the first page that is not `ok` stops the run. The page count the API
 * reports is bounded by {@link MAX_PAGES}; a larger claim stops the run.
 */
async function fetchPages(key: string): Promise<unknown[]> {
  const pages: unknown[] = [];
  let pageNumber = 1;
  let pageTotal = 1;

  while (pageNumber <= pageTotal) {
    const url = new URL(API_PATH, API_ORIGIN);
    url.searchParams.set('application_id', key);
    url.searchParams.set('language', 'en');
    url.searchParams.set('limit', String(PAGE_LIMIT));
    url.searchParams.set('page_no', String(pageNumber));
    url.searchParams.set('fields', API_FIELDS);

    const response = await fetch(url, { signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS) });
    const body: unknown = await response.json();

    if (!isRecord(body)) {
      throw new Error('vehicle-table: the API answer is not an object');
    }
    if (body['status'] !== 'ok') {
      const error = isRecord(body['error']) ? body['error'] : {};
      const code = typeof error['code'] === 'number' ? error['code'] : 'unknown';
      const message = typeof error['message'] === 'string' ? error['message'] : 'no message';
      // `error.value` is deliberately NOT read: it is where the API echoes
      // the offending parameter, which is the key. The message is payload
      // too, so the key is redacted out of it before it is printed.
      const safeMessage = message.split(key).join('[redacted]');
      throw new Error(`vehicle-table: the API returned error ${code}: ${safeMessage}`);
    }

    pages.push(body);

    const meta = isRecord(body['meta']) ? body['meta'] : null;
    const total = meta !== null && typeof meta['page_total'] === 'number' ? meta['page_total'] : 1;
    const claimed = Math.max(1, Math.trunc(total));
    // Fail closed: an answer that claims more pages than the table can hold is
    // not read further, and no further request carries the key.
    if (claimed > MAX_PAGES) {
      throw new Error(`vehicle-table: the API claims more than ${MAX_PAGES} pages`);
    }
    pageTotal = claimed;

    if (pageNumber < pageTotal) {
      await new Promise((resolve) => setTimeout(resolve, PAGE_PAUSE_MS));
    }
    pageNumber += 1;
  }

  return pages;
}

/**
 * Prove that a committed module is what this generator would have written.
 *
 * The check is OFFLINE: it imports the module, compares its row count and
 * its row hash with the metadata beside them, and re-runs the per-row rules
 * over the rows. It never calls the API and never writes.
 */
async function runCheck(options: Options): Promise<void> {
  const compared = options.against !== null ? path.resolve(options.against) : outputPath(options);

  let loaded: { VEHICLE_TABLE?: unknown; VEHICLE_TABLE_META?: unknown };
  try {
    loaded = (await import(pathToFileURL(compared).href)) as {
      VEHICLE_TABLE?: unknown;
      VEHICLE_TABLE_META?: unknown;
    };
  } catch {
    process.stderr.write(`vehicle-table: ${compared} could not be read as a table module\n`);
    process.exitCode = 1;
    return;
  }

  const rows = loaded.VEHICLE_TABLE;
  const meta = loaded.VEHICLE_TABLE_META;
  if (!Array.isArray(rows) || !isRecord(meta)) {
    process.stderr.write(`vehicle-table: ${compared} is not a table module\n`);
    process.exitCode = 1;
    return;
  }

  const count = meta['count'];
  if (typeof count !== 'number' || count !== rows.length) {
    process.stderr.write(`vehicle-table: ${compared} has a stale row count\n`);
    process.exitCode = 1;
    return;
  }

  let hash: string;
  try {
    hash = rowsHash(rows as VehicleTableRow[]);
  } catch {
    process.stderr.write(`vehicle-table: ${compared} has rows that cannot be hashed\n`);
    process.exitCode = 1;
    return;
  }
  if (hash !== meta['sha256']) {
    process.stderr.write(`vehicle-table: ${compared} has a stale row hash\n`);
    process.exitCode = 1;
    return;
  }

  if (rows.length > 0) {
    try {
      validateRows(rows);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'a row is invalid';
      process.stderr.write(`vehicle-table: ${compared} has an invalid row: ${message}\n`);
      process.exitCode = 1;
      return;
    }
  }

  process.stdout.write(`vehicle-table: count=${rows.length} up-to-date=${compared}\n`);
}

async function main(argv: readonly string[]): Promise<void> {
  const options = parseArgs(argv);

  if (options.check) {
    await runCheck(options);
    return;
  }

  let rows: VehicleTableRow[];

  if (options.empty) {
    // Nothing to validate: there is no payload.
    rows = [];
  } else if (options.from !== null) {
    const text = await readFile(path.resolve(options.from), 'utf8');
    const parsed: unknown = JSON.parse(text);
    rows = validatePages(parsed);
  } else {
    const envFilePath = path.resolve(REPO_ROOT, options.envFile);
    const key = readApplicationId(process.env, await readEnvFile(envFilePath));
    if (key === null) {
      process.stderr.write('WG_APPLICATION_ID is not set (environment or .env.local)\n');
      process.exitCode = 1;
      return;
    }
    rows = validatePages(await fetchPages(key));
  }

  const target = outputPath(options);
  const generated = renderModule(rows, todayUtc());
  await mkdir(path.dirname(target), { recursive: true });
  await writeFile(target, generated);
  process.stdout.write(`vehicle-table: count=${rows.length} out=${target}\n`);
}

// A module-local check rather than a bare call, so a test can import the flag
// parser and the helpers without running a generation.
if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    await main(process.argv.slice(2));
  } catch (error) {
    const message = error instanceof Error ? error.message : 'unknown failure';
    process.stderr.write(`${message}\n`);
    process.exitCode = 1;
  }
}
